using System.Text;

namespace Zendiator.SourceGenerator;

// Canonical orchestration is generated from the new contract. Each opaque Wrapper
// keeps its own boundary and receives a typed lazy upstream factory, never a reference adapter.
internal static class CanonicalStreamFallbackEmitter
{
    internal static CanonicalSourceFile Emit(CanonicalStreamFallbackModel model)
    {
        var b = new StringBuilder(); var h = model.Handler;
        b.AppendLine($$"""
            // <auto-generated/>
            #nullable enable
            // Unregistered canonical Stream candidate. Public acceptance remains blocked.
            namespace {{model.Namespace}}
            {
                internal static class {{model.ClassName}}{{model.Generic?.TypeParameters}}{{model.Generic?.TypeConstraints}}
                {
                    internal static global::System.Collections.Generic.IAsyncEnumerable<{{h.ItemName}}> Create(
                        global::System.IServiceProvider services, {{h.RequestName}} request,
                        global::System.Threading.CancellationToken token = default)
                    {
                        global::System.ArgumentNullException.ThrowIfNull(services);
                        global::System.ArgumentNullException.ThrowIfNull(request);
                        return new Envelope{{model.ConsumerSegment}}(services, request, token);
                    }
            """);
        foreach (var segment in model.Segments)
        {
            var n = segment.Id;
            if (segment.Upstream is { } upstream)
                b.AppendLine($$"""
                        private sealed class Upstream{{n}}(global::System.IServiceProvider services)
                            : global::Zendiator.IStreamUpstream<{{h.RequestName}}, {{h.ItemName}}>
                        {
                            public global::System.Collections.Generic.IAsyncEnumerable<{{h.ItemName}}> Open(
                                {{h.RequestName}} request, global::System.Threading.CancellationToken token)
                            {
                                global::System.ArgumentNullException.ThrowIfNull(request);
                                return new Envelope{{upstream}}(services, request, token);
                            }
                        }
                """);
            b.AppendLine($$"""
                    private sealed class Envelope{{n}}(global::System.IServiceProvider services, {{h.RequestName}} request,
                        global::System.Threading.CancellationToken api) : global::System.Collections.Generic.IAsyncEnumerable<{{h.ItemName}}>
                    {
                        public global::System.Collections.Generic.IAsyncEnumerator<{{h.ItemName}}> GetAsyncEnumerator(
                            global::System.Threading.CancellationToken enumeration = default) => new Cursor{{n}}(services, request, api, enumeration);
                    }
                    private sealed class Cursor{{n}}(global::System.IServiceProvider services, {{h.RequestName}} request,
                        global::System.Threading.CancellationToken api, global::System.Threading.CancellationToken enumeration)
                        : global::System.Collections.Generic.IAsyncEnumerator<{{h.ItemName}}>
                    {
                        private global::System.Collections.Generic.IAsyncEnumerator<{{h.ItemName}}>? _source;
                        private global::System.Threading.CancellationTokenSource? _linked;
                        private global::System.Threading.CancellationToken _token;
                        private bool _started, _ended, _disposed, _hasCurrent;
                        private int _busy;
                        private {{h.ItemName}} _current = default!;
            """);
            for (var i = 0; i < segment.Hooks.Count; i++) b.AppendLine("            private " + segment.Hooks[i].ContractName + "? _hook" + i + ";");
            b.AppendLine($$"""
                        public {{h.ItemName}} Current => _hasCurrent ? _current : throw new global::System.InvalidOperationException("Current is unavailable.");
                        private void Enter()
                        {
                            if (global::System.Threading.Interlocked.CompareExchange(ref _busy, 1, 0) != 0)
                                throw new global::System.InvalidOperationException("Await the preceding operation.");
                        }
                        public global::System.Threading.Tasks.ValueTask<bool> MoveNextAsync()
                        {
                            Enter(); _hasCurrent = false;
                            if (_ended || _disposed) { global::System.Threading.Volatile.Write(ref _busy, 0); return new(false); }
                            return Move();
                        }
                        private async global::System.Threading.Tasks.ValueTask<bool> Move()
                        {
                            try
                            {
                                if (!_started)
                                {
                                    _started = true;
                                    _token = !api.CanBeCanceled ? enumeration : !enumeration.CanBeCanceled || api == enumeration ? api
                                        : (_linked = global::System.Threading.CancellationTokenSource.CreateLinkedTokenSource(api, enumeration)).Token;
                                    _token.ThrowIfCancellationRequested();
            """);
            if (segment.Wrapper is { } wrapper)
                b.AppendLine($$"""
                                    var wrapper = ({{wrapper.ContractName}})global::Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions.GetRequiredService(services, typeof({{wrapper.WrapperName}}));
                                    // Direct-return Open keeps its replacement token: framework acquisition adds no outer enumeration token.
                                    _source = wrapper.{{wrapper.MethodName}}(request, new Upstream{{n}}(services), _token).GetAsyncEnumerator();
                """);
            else
                b.AppendLine($$"""
                                    var handler = ({{h.ContractName}})global::Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions.GetRequiredService(services, typeof({{h.HandlerName}}));
                                    _source = handler.{{h.MethodName}}(request, _token).GetAsyncEnumerator(_token);
                """);
            b.AppendLine("                    }");
            b.AppendLine("                    while (true)"); b.AppendLine("                    {");
            b.AppendLine("                        _token.ThrowIfCancellationRequested();");
            b.AppendLine("                        if (!await _source!.MoveNextAsync().ConfigureAwait(false))");
            b.AppendLine("                        { _ended = true; await Close().ConfigureAwait(false); return false; }");
            b.AppendLine("                        var item = _source!.Current;");
            for (var i = 0; i < segment.Hooks.Count; i++)
            {
                var hook = segment.Hooks[i];
                b.AppendLine("                        _token.ThrowIfCancellationRequested();");
                b.AppendLine("                        _hook" + i + " ??= (" + hook.ContractName + ")global::Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions.GetRequiredService(services, typeof(" + hook.HookName + "));");
                var call = "_hook" + i + "." + hook.MethodName + "(request, item, _token)";
                b.AppendLine(hook.Phase == BoundCallbackPhase.Filter ? "                        if (!" + call + ") continue;" : "                        item = " + call + ";");
            }
            b.AppendLine($$"""
                                    _current = item; _hasCurrent = true; return true;
                                }
                            }
                            catch { _ended = true; await Close().ConfigureAwait(false); throw; }
                            finally { global::System.Threading.Volatile.Write(ref _busy, 0); }
                        }
                        public global::System.Threading.Tasks.ValueTask DisposeAsync()
                        {
                            Enter(); _hasCurrent = false;
                            if (_disposed) { global::System.Threading.Volatile.Write(ref _busy, 0); return default; }
                            _disposed = _ended = true; return Dispose();
                        }
                        private async global::System.Threading.Tasks.ValueTask Dispose()
                        {
                            try { await Close().ConfigureAwait(false); }
                            finally { global::System.Threading.Volatile.Write(ref _busy, 0); }
                        }
                        private async global::System.Threading.Tasks.ValueTask Close()
                        {
                            var source = _source; var linked = _linked; _source = null; _linked = null;
                            try { if (source is not null) await source.DisposeAsync().ConfigureAwait(false); }
                            finally { linked?.Dispose(); }
                        }
                    }
            """);
        }
        b.AppendLine("    }"); b.AppendLine("}");
        return new(model.HintName, b.ToString());
    }
}
